// TH14 synthetic training aliases; see transcribe/th14/touhou-bullets.ecl.
// Native type 5 -> TH14_BALL2 (target row base 432), base radius 4, valid colors 0-15.
// Only the constants used by this card are copied in.
const TH14_BALL2: int = 432;

// TH14 v1.00b Stage 5 wave th14_s5_w01.
// Source: st05.ecl.txt MainSub00 509-522 (spawn schedule),
//         Phantom01 1003-1022 (body/motion), Phantom01_at 1024-1071 (fire loop).
// Source frame 0 = entry line 509; the wave is placed after the 120-frame shell buffer.

const TIME_LIMIT: int = 2124;
const OPENING_BUFFER: int = 120;

// Source Phantom01 body (1005-1021):
//   moveVel(-1.1780972f, 1.0f)
//   moveCircleRel(%RANDRAD, 0.017453292f, -1.1780972f, 0.0f)
//   moveCircleRelTime(80, 0, -999999.0f, 16.0f, 0.0f)
// REL circle: random phase, omega 1deg/frame, radius -1.178..16 over 80 linear ticks, d=0.
// ABS layer: constant polar velocity (1px/frame, -67.5deg); mirrored child flips x only.

// Source Phantom01_at (1026-1070) fire loop.
// etNew/etSprite(5,6)/etAim(0)/etCount(1,rank layers)/etAngle(0,0)/etSpeed(2,4|5)
// then diffWait/etOn, diffI(A,2,2,5,10), and A more volleys with diffWait/etOn.
// etEx ANIM a=1 keeps the -4*initial-speed spawn displacement (birth ANIM otherwise omitted).

sub volley(layers: int, last_speed: fx) {
    // Layer speed v(q) = s0 + (s1-s0)*q/(M-1); M=1 uses s0 only.
    var step: fx = 0fx;
    if layers > 1 { step = (last_speed - 2fx) / (layers - 1); }
    // Source layer order q outer with one angle path; per-layer fire keeps the
    // per-layer ANIM distance (4*velocity) exact.
    for q in 0..layers {
        var v: fx = 2fx + step * (q as fx);
        sh_speed(0, v, 0fx);
        sh_dist(0, (0fx - 4fx) * v);
        sh_fire(0);
    }
}

async sub phantom_at() {
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 6);   // etSprite(0, 5, 6)
    sh_ring(0, 0);                 // fan
    sh_aim(0, 1);                  // etAim(0, 0): self-aimed fan
    sh_count(0, 1, 1);             // etCount(0, 1, layers) is driven per volley
    sh_angle(0, 0deg, 0deg);       // etAngle(0, 0.0f, 0.0f)

    var rank: int = global(GVAR_RANK);
    var first: int = 0;
    var gap_base: int = 1;
    var gap_mod: int = 1;
    var layers: int = 1;
    var last_speed: fx = 4fx;
    // diffWait values: E 90+RAND%180 / N,H 60+RAND%40 / L 40+RAND%40 first;
    // then E 90+RAND%40 / N 30+RAND%40 / H,L 30+RAND%20.
    if rank == 0 {
        first = 90 + (rand(65536) % 180);
        gap_base = 90;
        gap_mod = 40;
    } else if rank == 1 {
        first = 60 + (rand(65536) % 40);
        gap_base = 30;
        gap_mod = 40;
    } else if rank == 2 {
        first = 60 + (rand(65536) % 40);
        gap_base = 30;
        gap_mod = 20;
        layers = 4;
    } else {
        first = 40 + (rand(65536) % 40);
        gap_base = 30;
        gap_mod = 20;
        layers = 8;
        last_speed = 5fx;
    }
    // diffI($A, 2, 2, 5, 10): further volleys after the first etOn.
    var shots: int = 2;
    if rank == 2 { shots = 5; }
    if rank == 3 { shots = 10; }

    wait(first);
    volley(layers, last_speed);
    for i in 0..shots {
        wait(gap_base + (rand(65536) % gap_mod));
        volley(layers, last_speed);
    }
}

async sub phantom_body(alpha: angle) {
    set_invuln(65535);
    set_hurtbox(14fx);    // setHurtbox(28,28): ordinary circle uses first*0.5
    set_hitbox(8fx);      // setHitbox(16,16): ordinary circle uses first*0.5
    spawn phantom_at();   // @Phantom01_at() async before the source movement setup

    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var vx: fx = 1fx * cos(alpha);
    var vy: fx = 1fx * sin(alpha);
    var theta: angle = (rand(65536) - 32768) as angle; // %RANDRAD, full -pi..pi domain
    var r: fx = 0fx - 1.1780972fx;                    // circle radius seed
    var dr: fx = (16fx - r) / 80;                     // linear radius interpolation over 80 ticks
    var prev_x: fx = x0;
    var prev_y: fx = y0;
    var n: int = 0;
    // Pre-arrange the next source movement tick; the engine integrates it after ECL.
    loop {
        var nx: fx = x0 + (n as fx) * vx + r * cos(theta);
        var ny: fx = y0 + (n as fx) * vy + r * sin(theta);
        move_vel_xy(0, nx - prev_x, ny - prev_y, EASE_LINEAR);
        prev_x = nx;
        prev_y = ny;
        n = n + 1;
        theta = theta + 1deg;
        if n <= 80 { r = r + dr; }
        wait(1);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // MainSub00: A=12; per iteration create mirror child, wait 20, create plain child, wait 20.
    for i in 0..12 {
        // enmCreateM(+, mirror=1): world x 128+RANDF*64, y 320+RANDF*32, HP 130.
        var ux: fx = (rand(32768) as fx) / 32768;
        var uy: fx = (rand(32768) as fx) / 32768;
        _ = spawn_enemy(128fx + ux * 64fx, 320fx + uy * 32fx, 130, 0, 1000, 0,
                        phantom_body(-112.5deg));
        wait(20);
        // enmCreate: world x -128-RANDF*64, same y range.
        var ux2: fx = (rand(32768) as fx) / 32768;
        var uy2: fx = (rand(32768) as fx) / 32768;
        _ = spawn_enemy(0fx - 128fx - ux2 * 64fx, 320fx + uy2 * 32fx, 130, 0, 1000, 0,
                        phantom_body(-67.5deg));
        wait(20);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
